extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve aprirsi senza errori"):
		return
	var ball := find_by_name(main, "Ball") as CharacterBody3D
	if not check("ball", ball != null, "Nella scena serve un CharacterBody3D chiamato Ball"):
		return

	await wait_physics_frames(60)
	check("ball_stopped", ball.global_position.y > 0.0, "La sfera deve fermarsi sulla piattaforma sopra y = 0 (attualmente si trova a y = %.2f)" % ball.global_position.y)

